@import "tailwindcss";

/* the animatable angle behind the liquid-glass card's travelling rim —
   @property has to be declared at the top level or Tailwind drops it */
@property --orbit { syntax: "<angle>"; initial-value: 0deg; inherits: false; }
@keyframes lgc-orbit { to { --orbit: 360deg; } }

@theme {
  /* Brand typeface (Plus Jakarta Sans / JetBrains Mono), injected as CSS vars by
     next/font in app/layout.tsx.
     Mapping them here makes Tailwind's `font-sans` / `font-mono` utilities — and the
     body default below — resolve to Geist, with a graceful system fallback. */
  --font-sans: var(--font-nx-sans), ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: var(--font-nx-mono), ui-monospace, "SFMono-Regular", "Menlo", monospace;

  /* Nexion's palette used to live HERE, in the bare theme — reusing
     production's own slot names (brand-*, navy-*, accent-*) plus a slate-*
     override Tailwind's stock scale never had in production at all. Since
     `@theme` custom properties cascade like any other CSS variable, that
     meant every one of the ~4,700 existing `bg-brand-500`/`text-slate-300`/
     etc. usages sitewide picked up the new values — including marketing,
     login, and admin, none of which were ever meant to change. Confirmed
     live: "buttons changed, motion graphics changed" on pages whose own
     files were byte-identical to production, because the shared color
     UNDERNEATH those unchanged files had moved.

     Fix: these slots stay at production's original values here, and the
     Nexion values move to `.nx-shell-root` below (the wrapper every
     dashboard page already renders inside, and ONLY the dashboard does) —
     the same scoping technique `.nx-dark-island` already uses successfully
     elsewhere in this file, one level up. */
  --color-brand-50: #f2f0ff;
  --color-brand-100: #e4e0ff;
  --color-brand-200: #c9c2ff;
