import type { Metadata } from "next";
import { Bodoni_Moda, DM_Mono, Libre_Franklin } from "next/font/google";
import "./v6.css";

/**
 * v6 — "Editorial". The one LIGHT-MODE concept of the bake-off, so it commits
 * fully: a cool paper ground, deep blue-black ink, and the vocabulary of a
 * printed monograph (indices, plates, figure keys, specification tables)
 * rather than the vocabulary of a SaaS landing page (cards, pills, glows).
 *
 * TYPE — three faces, each with exactly one job:
 *
 *  - Bodoni Moda (display). A real didone: hairline-to-fat stroke contrast that
 *    only makes sense on paper, and only at size. Used for headlines, section
 *    numerals, pull quotes and the price figures — never below ~20px, where a
 *    didone's thin strokes start to disappear.
 *  - Libre Franklin (text). A Franklin Gothic revival, i.e. a genuine
 *    newspaper/editorial text face rather than a UI grotesque. Carries every
 *    paragraph, every link, every table cell of prose.
 *  - DM Mono (labels & figures). The technical voice: small-caps-ish tracked
 *    labels, figure numbers, coordinates, tabular data.
 *
 * Deliberately NOT Inter, Geist or Space Grotesk (the brief rules them out, and
 * Geist is what the root layout already loads site-wide), and deliberately not
 * the Archivo / Familjen Grotesk / IBM Plex that the three sibling concepts
 * reached for, so this page cannot be confused with any of them at a glance.
 */
const display = Bodoni_Moda({
  subsets: ["latin"],
  style: ["normal", "italic"],
  variable: "--font-v6-display",
  display: "swap",
});

const text = Libre_Franklin({
  subsets: ["latin"],
  style: ["normal", "italic"],
  variable: "--font-v6-text",
  display: "swap",
});

const figure = DM_Mono({
  subsets: ["latin"],
  weight: ["300", "400", "500"],
  variable: "--font-v6-mono",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Nxeon — a working catalogue",
  description:
    "Servers, sites and game worlds in two regions: Singapore and Germany. The whole price list, as printed.",
  // Concept page for an internal bake-off — must never reach an index.
  robots: { index: false, follow: false },
};

export default function V6Layout({ children }: { children: React.ReactNode }) {
  return (
    <div className={`v6 ${display.variable} ${text.variable} ${figure.variable}`}>
      {children}
    </div>
  );
}

/**
 * The page's table of contents — read by the server page (to stamp the section
 * anchors), by the running head in the masthead, and by the fixed side index.
 *
 * Plain module, NO "use client": it is imported from both a Server Component
 * and two Client Components, and a "use client" module whose exports are read
 * from the server page is the exact trap that resolves to `undefined` at render
 * time. Data only — no components live here.
 */
export type SectionDef = {
  /** DOM id stamped on the <section>; also the scroll target. */
  id: string;
  /** Folio numeral, set in the display face. */
  num: string;
  /** Running-head label. */
  label: string;
};

export const SECTIONS: SectionDef[] = [
  { id: "v6-front", num: "—", label: "Front matter" },
  { id: "v6-catalogue", num: "I", label: "The catalogue" },
  { id: "v6-rooms", num: "II", label: "Two rooms" },
  { id: "v6-spec", num: "III", label: "Specification" },
  { id: "v6-colophon", num: "IV", label: "Colophon" },
];

/**
 * Shared inline marks. NO "use client" on purpose — these are rendered from
 * both the Server Component page and the client components in this directory,
 * and they are exported as INDIVIDUAL named functions rather than as properties
 * of one exported object. An object-of-components exported from a "use client"
 * module resolves to `undefined` when a Server Component reads a property off
 * it, and React then throws "Element type is invalid".
 */

/** Editorial arrow — a hairline stem with a small head, to match the rules. */
export function Arrow({ size = 13 }: { size?: number }) {
  return (
    <svg
      className="v6-arrow"
      width={size}
      height={size}
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      focusable="false"
    >
      <path d="M1.5 8h12" stroke="currentColor" strokeWidth="1.1" />
      <path d="M9 3.5 13.5 8 9 12.5" stroke="currentColor" strokeWidth="1.1" fill="none" />
    </svg>
  );
}

/** A printer's dagger, used for the licence footnote in the image index. */
export function Dagger() {
  return (
    <span className="v6-dagger" aria-hidden="true">
      †
    </span>
  );
}

/** Lozenge used as a rule terminal / list bullet. */
export function Lozenge() {
  return (
    <svg width="7" height="7" viewBox="0 0 8 8" aria-hidden="true" focusable="false">
      <path d="M4 0 8 4 4 8 0 4Z" fill="currentColor" />
    </svg>
  );
}

/* ===========================================================================
   Nxeon v6 — "Editorial". The bake-off's only LIGHT concept.

   Every rule is scoped under `.v6`. The root layout's globals.css is a
   dark-first system: `body` carries a hardcoded #060a14 ground with two fixed
   radial washes and a light text colour, and ~4,700 Tailwind colour utilities
   sitewide resolve against a dark palette. So this file:

     - paints its OWN ground and ink on `.v6` (never inherits a token), and
       pins a fixed paper layer behind the page so an overscroll bounce or a
       short viewport can't reveal the dark body underneath;
     - uses NO Tailwind utilities at all in the markup. That is partly taste
       (a print page wants named editorial classes, not utility soup) and
       partly defence: a scoped rule like `.v6 .plate { position: relative }`
       has specificity 0,2,0 and silently beats Tailwind's `lg:absolute`
       (0,1,0). With no utilities in play there is nothing to lose that fight.

   PALETTE — a cool paper, explicitly NOT the warm-cream / terracotta /
   broadsheet-hairline look, which is the single most recognisable
   AI-generated-design cliché. The ground is a blue-biased off-white, the ink
   is a deep blue-black, and the accent is a printerly violet-blue drawn from
   the brand's own blue -> violet gradient. Saturated colour is left to the
   photographic plates: on paper the dark neon artwork does all the shouting,
   which is exactly how a monograph works.
   =========================================================================== */

.v6 {
  /* ---- ground ---------------------------------------------------------- */
  --paper: #eff1f6; /* cool blue-grey paper — the page */
  --plate: #fafbfd; /* brighter stock — plates, tables, raised sheets */
  --press: #e3e7ef; /* pressed band — sunken sections */
  --press-deep: #d9dee8; /* pressed band, second step */

  /* ---- ink ------------------------------------------------------------- */
  --ink: #11151e; /* deep blue-black, never pure black */
  --ink-soft: #454f61; /* body copy */
  --ink-mute: #78829a; /* captions, labels, folios */
  --ink-faint: #a3abbd;

  /* ---- rules ----------------------------------------------------------- */
  --rule: #c4cbd9; /* visible division */
  --hair: #dbe0ea; /* hairline between index rows */

  /* ---- accent: ink and highlighter, not a brand wash ------------------- */
  --violet: #4a1fcc; /* printerly violet ink — rules, markers, one solid CTA */
  --electric: #1a52d6; /* brand blue, for links */
  --wash: #d6e1ff; /* highlighter block behind hovered words */

  --edge: clamp(18px, 4.6vw, 68px);
  --measure: 1280px;

  position: relative;
  isolation: isolate;
  min-height: 100vh;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-v6-text), "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  font-synthesis-weight: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

/* The fixed paper backdrop. `body` keeps its dark gradient (not ours to
   change), so this covers the viewport regardless of scroll position. */
.v6::before {
  content: "";
  position: fixed;
  inset: -20vh 0;
  z-index: -1;
  background: var(--paper);
  pointer-events: none;
}

.v6 *,
.v6 *::before,
.v6 *::after {
  box-sizing: border-box;
}

.v6 a {
  color: inherit;
  text-decoration: none;
}

.v6 ::selection {
  background: var(--wash);
  color: var(--ink);
}

.v6 :focus-visible {
  outline: 2px solid var(--violet);
  outline-offset: 3px;
}

.v6 img {
  display: block;
  max-width: 100%;
}

.v6 p,
.v6 h1,
.v6 h2,
.v6 h3,
.v6 figure,
.v6 ol,
.v6 ul,
.v6 table {
  margin: 0;
  padding: 0;
}

.v6 ol,
.v6 ul {
  list-style: none;
}

/* ---------------------------------------------------------------------------
   MEASURE
   --------------------------------------------------------------------------- */
.v6 .sheet {
  width: 100%;
  max-width: var(--measure);
  margin-inline: auto;
  padding-inline: var(--edge);
}

/* ---------------------------------------------------------------------------
   TYPE
   --------------------------------------------------------------------------- */
.v6 .disp {
  font-family: var(--font-v6-display), "Didot", "Bodoni MT", Georgia, serif;
  font-weight: 500;
  font-optical-sizing: auto;
  color: var(--ink);
  letter-spacing: -0.005em;
}

.v6 .disp em,
.v6 .disp i {
  font-style: italic;
  font-weight: 400;
}

.v6 .mono {
  font-family: var(--font-v6-mono), ui-monospace, "SFMono-Regular", Menlo, monospace;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
}

/* Tracked-out technical label. The page's third voice. */
.v6 .lab {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10.5px;
  font-weight: 400;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--ink-mute);
  line-height: 1.5;
}

.v6 .lab-ink {
  color: var(--ink);
}

.v6 .h-xl {
  font-size: clamp(38px, 7.1vw, 90px);
  line-height: 0.97;
}

.v6 .h-lg {
  font-size: clamp(30px, 4.4vw, 56px);
  line-height: 1.03;
}

.v6 .h-md {
  font-size: clamp(22px, 2.5vw, 31px);
  line-height: 1.15;
}

.v6 .deck {
  font-size: clamp(16.5px, 1.35vw, 19.5px);
  line-height: 1.62;
  color: var(--ink-soft);
  max-width: 63ch;
}

.v6 .deck strong {
  font-weight: 600;
  color: var(--ink);
}

/* A real drop cap, three lines deep, set in the display face. */
.v6 .drop::first-letter {
  font-family: var(--font-v6-display), Georgia, serif;
  font-weight: 500;
  font-size: 4.05em;
  line-height: 0.78;
  float: left;
  padding: 0.06em 0.09em 0 0;
  color: var(--ink);
}

.v6 .cap {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--ink-mute);
  letter-spacing: 0.01em;
}

.v6 .cap b {
  font-weight: 500;
  color: var(--ink);
}

/* Highlighter: a wash block that sits behind the lower two-fifths of a word,
   the way a marker pen does. Used for hover states on editorial links. */
.v6 .hl {
  background-image: linear-gradient(transparent 58%, var(--wash) 58%, var(--wash) 94%, transparent 94%);
  background-size: 0% 100%;
  background-repeat: no-repeat;
  transition: background-size 0.24s ease;
}

.v6 a:hover .hl,
.v6 a:focus-visible .hl {
  background-size: 100% 100%;
}

/* ---------------------------------------------------------------------------
   RULES — three weights, like a printed page
   --------------------------------------------------------------------------- */
.v6 .rule-ink {
  border-top: 1px solid var(--ink);
}
.v6 .rule {
  border-top: 1px solid var(--rule);
}
.v6 .rule-hair {
  border-top: 1px solid var(--hair);
}

/* ---------------------------------------------------------------------------
   MASTHEAD
   --------------------------------------------------------------------------- */
.v6 .mast {
  position: sticky;
  top: 0;
  z-index: 40;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: saturate(150%) blur(10px);
  -webkit-backdrop-filter: saturate(150%) blur(10px);
  border-bottom: 1px solid var(--rule);
}

.v6 .mast-in {
  display: flex;
  align-items: center;
  gap: 20px;
  min-height: 64px;
}

.v6 .brand {
  display: flex;
  align-items: center;
  gap: 11px;
  flex: 0 0 auto;
}

.v6 .brand img {
  height: 25px;
  width: auto;
}

/* The wordmark is TYPESET here rather than taken from /logo.png: that file's
   "NXEON" lettering is near-white (#e0e0e0) and disappears on paper. Only the
   NX monogram (/nx-mark.png, a blue->violet gradient) is used as artwork. */
.v6 .wordmark {
  font-family: var(--font-v6-text), Helvetica, Arial, sans-serif;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--ink);
  padding-top: 2px;
}

.v6 .mast-nav {
  display: flex;
  align-items: baseline;
  gap: clamp(14px, 1.9vw, 30px);
  margin-left: auto;
}

.v6 .mast-nav a {
  font-size: 14px;
  color: var(--ink-soft);
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
  transition: color 0.16s ease, border-color 0.16s ease;
}

.v6 .mast-nav a:hover {
  color: var(--ink);
  border-bottom-color: var(--violet);
}

/* Running head: the folio strip a book prints at the top of every page. Here
   it names whichever section you are currently reading. */
.v6 .runhead {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 190px;
  justify-content: flex-end;
  text-align: right;
}

.v6 .runhead .rh-num {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 16px;
  line-height: 1;
  color: var(--violet);
  min-width: 14px;
  text-align: right;
}

.v6 .mast-sign {
  display: none;
}

.v6 .contents-btn {
  display: none;
  appearance: none;
  border: 1px solid var(--rule);
  background: transparent;
  color: var(--ink);
  border-radius: 0;
  padding: 7px 12px;
  cursor: pointer;
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.v6 .contents-panel {
  border-top: 1px solid var(--hair);
  background: var(--plate);
}

.v6 .contents-panel ul {
  padding: 8px 0 16px;
}

.v6 .contents-panel a {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 0;
  border-bottom: 1px solid var(--hair);
  font-size: 16px;
}

/* ---------------------------------------------------------------------------
   SIDE INDEX — the scroll-tracking table of contents, in the left gutter
   --------------------------------------------------------------------------- */
.v6 .sidex {
  display: none;
}

@media (min-width: 1440px) {
  .v6 .sidex {
    display: block;
    position: fixed;
    left: 26px;
    top: 50%;
    transform: translateY(-50%);
    z-index: 30;
    width: 128px;
  }

  .v6 .sidex ol {
    display: grid;
    gap: 2px;
  }

  .v6 .sidex a {
    display: grid;
    grid-template-columns: 22px 1fr;
    align-items: baseline;
    gap: 8px;
    padding: 7px 0 6px;
    border-top: 1px solid var(--hair);
    color: var(--ink-faint);
    transition: color 0.2s ease, border-color 0.2s ease;
  }

  .v6 .sidex a:hover {
    color: var(--ink);
  }

  .v6 .sidex .sx-num {
    font-family: var(--font-v6-display), Georgia, serif;
    font-size: 13px;
    line-height: 1.4;
  }

  .v6 .sidex .sx-lab {
    font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
    font-size: 10px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    line-height: 1.5;
  }

  .v6 .sidex a[data-on="1"] {
    color: var(--ink);
    border-top-color: var(--violet);
  }

  .v6 .sidex a[data-on="1"] .sx-num {
    color: var(--violet);
  }
}

/* ---------------------------------------------------------------------------
   BUTTONS — two, and no third. A solid ink block and an underlined text link.
   No pills, no gradients, no glow.
   --------------------------------------------------------------------------- */
.v6 .btn-ink {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  background: var(--ink);
  color: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 0;
  padding: 15px 24px 14px;
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 11.5px;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  transition: background-color 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.v6 .btn-ink:hover {
  background: var(--violet);
  border-color: var(--violet);
  transform: translateY(-1px);
}

.v6 .btn-ink .v6-arrow {
  transition: transform 0.2s ease;
}

.v6 .btn-ink:hover .v6-arrow {
  transform: translateX(3px);
}

.v6 .btn-text {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 15px 2px 14px;
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 11.5px;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  color: var(--ink);
  border-bottom: 1px solid var(--ink);
  transition: color 0.18s ease, border-color 0.18s ease;
}

.v6 .btn-text:hover {
  color: var(--violet);
  border-bottom-color: var(--violet);
}

.v6 .btn-text:hover .v6-arrow {
  transform: translateX(3px);
}

.v6 .btn-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(14px, 2.4vw, 34px);
}

/* ---------------------------------------------------------------------------
   HERO
   --------------------------------------------------------------------------- */
.v6 .hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 286px;
  gap: clamp(30px, 5.4vw, 76px);
  align-items: start;
  padding-top: clamp(40px, 6.5vw, 86px);
  padding-bottom: clamp(34px, 4.4vw, 58px);
}

.v6 .hero-kicker {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 20px;
}

.v6 .hero-kicker .kick-rule {
  flex: 1 1 auto;
  height: 1px;
  background: var(--rule);
  max-width: 180px;
}

.v6 .hero h1 {
  max-width: 17ch;
}

.v6 .hero .deck {
  padding-top: clamp(20px, 2.4vw, 32px);
}

.v6 .hero .btn-row {
  padding-top: clamp(24px, 3vw, 38px);
}

/* The colophon: a printed data box, not four equal stat tiles. Mono label
   above, display figure below, hairline between each entry. */
.v6 .colophon {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}

.v6 .cph-row {
  display: grid;
  gap: 1px;
  padding: 11px 0 12px;
  border-bottom: 1px solid var(--hair);
}

.v6 .cph-row:last-child {
  border-bottom: 0;
}

.v6 .cph-val {
  font-family: var(--font-v6-display), Georgia, serif;
  font-weight: 500;
  font-size: 28px;
  line-height: 1.1;
  color: var(--ink);
  font-variant-numeric: lining-nums;
}

.v6 .cph-val small {
  font-family: var(--font-v6-text), Helvetica, Arial, sans-serif;
  font-size: 12.5px;
  font-weight: 400;
  letter-spacing: 0.01em;
  color: var(--ink-mute);
  padding-left: 5px;
}

.v6 .cph-sub {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 11px;
  color: var(--ink-mute);
  padding-top: 3px;
  letter-spacing: 0.01em;
}

/* ---------------------------------------------------------------------------
   PLATE 01 — the portal montage, tipped in at full measure with a figure key
   --------------------------------------------------------------------------- */
.v6 .plate-band {
  background: var(--press);
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}

.v6 .plate-wrap {
  padding-block: clamp(26px, 3.6vw, 52px);
}

.v6 .plate-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 16px;
}

.v6 .plate-stage {
  position: relative;
  background: var(--plate);
  border: 1px solid var(--rule);
  padding: clamp(10px, 1.6vw, 26px);
  box-shadow: 0 22px 46px -34px rgba(17, 21, 30, 0.42);
}

.v6 .plate-stage > img {
  width: 100%;
  height: auto;
}

/* Numbered markers laid over the plate. Each is always visible — nothing on
   this page waits at opacity 0 for an observer. */
.v6 .fig-mark {
  position: absolute;
  width: 23px;
  height: 23px;
  margin: -11px 0 0 -11px;
  border-radius: 50%;
  border: 1px solid var(--violet);
  background: color-mix(in srgb, var(--plate) 82%, transparent);
  color: var(--violet);
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10.5px;
  line-height: 21px;
  text-align: center;
  cursor: pointer;
  padding: 0;
  transition: background-color 0.18s ease, color 0.18s ease, transform 0.18s ease;
}

.v6 .fig-mark[data-on="1"] {
  background: var(--violet);
  color: #fff;
  transform: scale(1.14);
}

.v6 .fig-key {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0 clamp(14px, 2vw, 28px);
  padding-top: clamp(18px, 2.2vw, 28px);
  align-items: start;
}

.v6 .fig-key > div {
  border-top: 1px solid var(--rule);
}

.v6 .fig-key button {
  appearance: none;
  background: transparent;
  border: 0;
  border-radius: 0;
  width: 100%;
  text-align: left;
  padding: 11px 0 4px;
  cursor: pointer;
  color: inherit;
  display: flex;
  align-items: baseline;
  gap: 8px;
  font: inherit;
}

.v6 .fig-key .fk-n {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10.5px;
  color: var(--violet);
  letter-spacing: 0.1em;
}

.v6 .fig-key .fk-t {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 19px;
  line-height: 1.2;
  color: var(--ink);
}

.v6 .fig-key button:hover .fk-t {
  color: var(--violet);
}

.v6 .fig-key .fk-body {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.28s ease;
}

.v6 .fig-key [data-open="1"] .fk-body {
  grid-template-rows: 1fr;
}

.v6 .fig-key .fk-body > div {
  overflow: hidden;
}

.v6 .fig-key .fk-body p {
  font-size: 14px;
  line-height: 1.55;
  color: var(--ink-soft);
  padding: 2px 0 14px;
}

.v6 .fig-key .fk-more {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-faint);
  padding-bottom: 12px;
}

.v6 .fig-key [data-open="1"] .fk-more {
  display: none;
}

/* ---------------------------------------------------------------------------
   FULL-BLEED COLOUR PLATE — the one dark image on a light page, at real scale
   --------------------------------------------------------------------------- */
.v6 .bleed-plate {
  width: 100%;
  margin: 0;
}

.v6 .bleed-plate .bp-img {
  width: 100%;
  height: clamp(280px, 46vw, 560px);
  object-fit: cover;
  object-position: 50% 42%;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--rule);
}

.v6 .bleed-plate figcaption {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px 22px;
  padding-top: 11px;
}

/* ---------------------------------------------------------------------------
   SECTION OPENERS
   --------------------------------------------------------------------------- */
.v6 .sec {
  padding-block: clamp(56px, 8vw, 118px);
}

.v6 .sec-tight {
  padding-block: clamp(40px, 5vw, 72px);
}

.v6 .opener {
  display: grid;
  grid-template-columns: 96px minmax(0, 1fr);
  gap: clamp(18px, 3vw, 44px);
  align-items: start;
  padding-bottom: clamp(30px, 4vw, 54px);
}

.v6 .opener .op-num {
  font-family: var(--font-v6-display), Georgia, serif;
  font-weight: 400;
  font-size: clamp(44px, 5.4vw, 74px);
  line-height: 0.82;
  color: var(--violet);
  border-top: 1px solid var(--violet);
  padding-top: 12px;
}

.v6 .opener .op-lab {
  padding-bottom: 14px;
}

.v6 .opener .op-body {
  border-top: 1px solid var(--ink);
  padding-top: 12px;
}

.v6 .opener h2 {
  max-width: 22ch;
  padding-bottom: clamp(16px, 1.8vw, 24px);
}

/* ---------------------------------------------------------------------------
   I — THE CATALOGUE: a picture index
   --------------------------------------------------------------------------- */
.v6 .cat {
  display: grid;
  grid-template-columns: 310px minmax(0, 1fr);
  gap: clamp(24px, 4vw, 60px);
  align-items: start;
}

.v6 .cat-plate-col {
  position: sticky;
  top: 96px;
}

.v6 .cat-plate {
  position: relative;
  aspect-ratio: 3 / 4;
  background: var(--press-deep);
  border: 1px solid var(--rule);
  overflow: hidden;
  box-shadow: 0 20px 44px -32px rgba(17, 21, 30, 0.5);
}

.v6 .cat-plate img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.v6 .cat-plate img[data-on="1"] {
  opacity: 1;
}

.v6 .cat-plate-cap {
  padding-top: 11px;
  border-top: 1px solid var(--hair);
  margin-top: 11px;
}

.v6 .cat-plate-cap .cpc-name {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 21px;
  line-height: 1.2;
  color: var(--ink);
  padding-bottom: 3px;
}

.v6 .cat-index {
  border-top: 1px solid var(--ink);
}

.v6 .cat-cols {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 118px 74px 62px 92px;
  gap: 0 14px;
  align-items: baseline;
  padding: 9px 0;
  border-bottom: 1px solid var(--rule);
}

.v6 .cat-row a {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) 118px 74px 62px 92px;
  gap: 0 14px;
  align-items: baseline;
  padding: 9px 0;
  border-bottom: 1px solid var(--hair);
  transition: background-color 0.16s ease;
}

.v6 .cat-row a:hover {
  background: color-mix(in srgb, var(--wash) 46%, transparent);
}

.v6 .cat-num {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 11px;
  color: var(--ink-faint);
  font-variant-numeric: tabular-nums;
}

.v6 .cat-name {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 20px;
  line-height: 1.25;
  color: var(--ink);
  letter-spacing: -0.003em;
}

.v6 .cat-row a:hover .cat-name {
  color: var(--violet);
}

.v6 .cat-gen,
.v6 .cat-num-cell {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 11px;
  color: var(--ink-mute);
  font-variant-numeric: tabular-nums;
}

.v6 .cat-num-cell {
  text-align: right;
}

.v6 .cat-price {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 18px;
  color: var(--ink);
  text-align: right;
  font-variant-numeric: tabular-nums lining-nums;
}

.v6 .cat-price em {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10px;
  font-style: normal;
  color: var(--ink-faint);
  letter-spacing: 0.08em;
  padding-right: 4px;
}

.v6 .cat-thumb {
  display: none;
}

.v6 .cat-foot {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 26px;
  justify-content: space-between;
  padding-top: 14px;
}

/* ---------------------------------------------------------------------------
   II — TWO ROOMS
   --------------------------------------------------------------------------- */
.v6 .rooms-lead {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 0.75fr);
  gap: clamp(24px, 4vw, 64px);
  align-items: center;
  padding-bottom: clamp(30px, 4vw, 52px);
}

.v6 .pull {
  font-family: var(--font-v6-display), Georgia, serif;
  font-weight: 400;
  font-style: italic;
  font-size: clamp(23px, 2.7vw, 35px);
  line-height: 1.2;
  color: var(--ink);
  border-left: 2px solid var(--violet);
  padding-left: clamp(16px, 2vw, 26px);
  max-width: 30ch;
}

.v6 .rooms-art {
  justify-self: center;
}

.v6 .rooms-art img {
  width: clamp(150px, 20vw, 232px);
  height: auto;
}

.v6 .rooms-art figcaption {
  padding-top: 10px;
  text-align: center;
}

.v6 .rooms {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  border-top: 1px solid var(--ink);
  border-bottom: 1px solid var(--ink);
  align-items: start;
}

.v6 .room {
  padding: clamp(20px, 2.8vw, 36px) clamp(18px, 2.6vw, 34px);
}

.v6 .room + .room {
  border-left: 1px solid var(--rule);
}

.v6 .room-ord {
  font-family: var(--font-v6-display), Georgia, serif;
  font-weight: 400;
  font-size: clamp(52px, 7vw, 92px);
  line-height: 0.82;
  color: var(--press-deep);
  padding-bottom: 8px;
  font-variant-numeric: lining-nums;
}

.v6 .room h3 {
  font-family: var(--font-v6-display), Georgia, serif;
  font-weight: 500;
  font-size: clamp(26px, 3.1vw, 40px);
  line-height: 1.05;
  color: var(--ink);
  margin: 0;
  padding-bottom: 14px;
}

.v6 .room dl {
  margin: 0;
  display: grid;
  gap: 0;
}

.v6 .room .room-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 0;
  border-top: 1px solid var(--hair);
}

.v6 .room .room-line dt {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-mute);
}

.v6 .room .room-line dd {
  margin: 0;
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 12.5px;
  color: var(--ink);
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.v6 .rooms-note {
  padding-top: 14px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px 24px;
  justify-content: space-between;
}

/* ---------------------------------------------------------------------------
   III — SPECIFICATION
   --------------------------------------------------------------------------- */
.v6 .spec-band {
  background: var(--press);
  border-top: 1px solid var(--rule);
  border-bottom: 1px solid var(--rule);
}

.v6 .spec-scroll {
  overflow-x: auto;
}

.v6 table.spec {
  width: 100%;
  min-width: 720px;
  border-collapse: collapse;
  background: var(--plate);
}

.v6 table.spec th,
.v6 table.spec td {
  text-align: right;
  padding: 13px 14px;
  border-bottom: 1px solid var(--hair);
  white-space: nowrap;
}

.v6 table.spec th:first-child,
.v6 table.spec td:first-child {
  text-align: left;
  padding-left: clamp(14px, 1.8vw, 24px);
}

.v6 table.spec td:last-child,
.v6 table.spec th:last-child {
  padding-right: clamp(14px, 1.8vw, 24px);
}

.v6 table.spec thead th {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 10px;
  font-weight: 400;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink-mute);
  border-bottom: 1px solid var(--ink);
  padding-block: 11px;
}

.v6 table.spec tbody tr:last-child td {
  border-bottom: 0;
}

.v6 table.spec .sp-name {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 22px;
  line-height: 1.15;
  color: var(--ink);
}

.v6 table.spec .sp-fig {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 13px;
  color: var(--ink-soft);
  font-variant-numeric: tabular-nums;
}

.v6 table.spec .sp-price {
  font-family: var(--font-v6-display), Georgia, serif;
  font-size: 22px;
  color: var(--ink);
  font-variant-numeric: tabular-nums lining-nums;
}

.v6 table.spec .sp-renew {
  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
  font-size: 13px;
  color: var(--ink-mute);
  font-variant-numeric: tabular-nums;
}

.v6 .spec-note {
  display: grid;
  gap: 8px;
  padding-top: 16px;
  max-width: 78ch;
}

.v6 .spec-note p {
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink-soft);
}

/* the one-click image index */
.v6 .imgs {
  padding-top: clamp(36px, 5vw, 64px);
}

.v6 .imgs-list {
  columns: 4;
  column-gap: clamp(18px, 2.4vw, 34px);
  column-rule: 1px solid var(--hair);
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}

.v6 .imgs-list li {
  break-inside: avoid;
  font-size: 13.5px;
  line-height: 1.5;
  color: var(--ink-soft);
  padding: 3px 0;
}

.v6 .imgs-group {
  break-inside: avoid;
  padding-bottom: 16px;
}

.v6 .imgs-group > .lab {
  padding-bottom: 6px;
  border-bottom: 1px solid var(--hair);
  margin-bottom: 6px;
}

.v6 .v6-dagger {
  color: var(--violet);
  padding-left: 3px;
  font-size: 12px;
}

/* ---------------------------------------------------------------------------
   IV — COLOPHON / CLOSE
   --------------------------------------------------------------------------- */
.v6 .close {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.62fr);
  gap: clamp(26px, 4vw, 68px);
  align-items: end;
  padding-bottom: clamp(44px, 6vw, 82px);
}

.v6 .close h2 {
  max-width: 15ch;
}

.v6 .close-side {
  border-top: 1px solid var(--ink);
  padding-top: 14px;
}

.v6 .foot {
  border-top: 1px solid var(--ink);
  padding-top: clamp(26px, 3.4vw, 42px);
  padding-bottom: clamp(34px, 4vw, 56px);
}

.v6 .foot-cols {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) repeat(3, minmax(0, 1fr));
  gap: clamp(20px, 3vw, 44px);
  align-items: start;
}

.v6 .foot-cols ul {
  display: grid;
  gap: 5px;
  padding-top: 10px;
}

.v6 .foot-cols a {
  font-size: 14px;
  color: var(--ink-soft);
}

.v6 .foot-cols a:hover {
  color: var(--violet);
}

.v6 .foot-brand img {
  height: 30px;
  width: auto;
}

.v6 .foot-brand p {
  padding-top: 12px;
  font-size: 13.5px;
  line-height: 1.6;
  color: var(--ink-mute);
  max-width: 34ch;
}

.v6 .foot-fine {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 24px;
  justify-content: space-between;
  border-top: 1px solid var(--hair);
  margin-top: clamp(24px, 3vw, 38px);
  padding-top: 14px;
}

/* ---------------------------------------------------------------------------
   RESPONSIVE
   --------------------------------------------------------------------------- */
@media (max-width: 1080px) {
  .v6 .hero {
    grid-template-columns: minmax(0, 1fr);
  }

  .v6 .hero h1 {
