"use client";

import { useEffect, useState } from "react";
import { SECTIONS } from "./sections";

/**
 * Which section the reader is currently in. A plain rAF-throttled scroll probe
 * rather than an IntersectionObserver: "the section whose top has most recently
 * passed a line a third of the way down the viewport" is exactly what a running
 * head wants, and IO's per-element ratios have to be reduced back to that
 * anyway. Returns the id of the current section, defaulting to the first, so
 * every consumer has a correct value on the very first paint — nothing on this
 * page is hidden waiting for an observer to fire.
 */
export function useCurrentSection(): string {
  const [active, setActive] = useState<string>(SECTIONS[0].id);

  useEffect(() => {
    let frame = 0;

    const read = () => {
      frame = 0;
      const probe = window.innerHeight * 0.34;
      let current = SECTIONS[0].id;
      for (const s of SECTIONS) {
        const el = document.getElementById(s.id);
        if (!el) continue;
        if (el.getBoundingClientRect().top <= probe) current = s.id;
      }
      setActive((prev) => (prev === current ? prev : current));
    };

    const onScroll = () => {
      if (frame) return;
      frame = window.requestAnimationFrame(read);
    };

    read();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      if (frame) window.cancelAnimationFrame(frame);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  return active;
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { SECTIONS } from "./sections";
import { useCurrentSection } from "./useCurrentSection";

/**
 * The masthead, with a RUNNING HEAD on the right: the folio strip a printed
 * book carries at the top of every page, here naming whichever section the
 * reader is currently in. Same scroll probe as the fixed side index, so the two
 * never disagree.
 *
 * The brand wordmark is TYPESET, not taken from /logo.png — that file's "NXEON"
 * lettering is near-white and vanishes on paper. Only the NX monogram
 * (/nx-mark.png, blue -> violet) is used as artwork; it reads cleanly here.
 */
const NAV: [string, string][] = [
  ["Game servers", "/game-servers"],
  ["Cloud VPS", "/vps"],
  ["Hosting", "/web-hosting"],
  ["Domains", "/domains"],
  ["Mods", "/mods"],
  ["Price list", "/pricing"],
];

export function Masthead() {
  const [open, setOpen] = useState(false);
  const current = useCurrentSection();
  const section = SECTIONS.find((s) => s.id === current) ?? SECTIONS[0];

  return (
    <header className="mast">
      <div className="sheet mast-in">
        <Link href="/newwebsitev6" className="brand" aria-label="Nxeon">
          <img src="/nx-mark.png" alt="" width={61} height={30} />
          <span className="wordmark">Nxeon</span>
        </Link>

        <nav className="mast-nav" aria-label="Sections">
          {NAV.map(([label, href]) => (
            <Link key={href} href={href}>
              {label}
            </Link>
          ))}
        </nav>

        <div className="runhead" aria-hidden="true">
          <span className="rh-num disp">{section.num}</span>
          <span className="lab">{section.label}</span>
        </div>

        <span className="mast-sign lab" aria-hidden="true">
          {section.label}
        </span>

        <button
          type="button"
          className="contents-btn"
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
        >
          {open ? "Close" : "Contents"}
        </button>
      </div>

      {open ? (
        <div className="contents-panel">
          <div className="sheet">
            <ul>
              {NAV.map(([label, href]) => (
                <li key={href}>
                  <Link href={href} onClick={() => setOpen(false)}>
                    <span>{label}</span>
                    <span className="lab">→</span>
                  </Link>
                </li>
              ))}
              <li>
                <Link href="/register" onClick={() => setOpen(false)}>
                  <span>Deploy a server</span>
                  <span className="lab">→</span>
                </Link>
              </li>
              <li>
                <Link href="/login" onClick={() => setOpen(false)}>
                  <span>Sign in</span>
                  <span className="lab">→</span>
                </Link>
              </li>
            </ul>
          </div>
        </div>
      ) : null}
    </header>
  );
}

"use client";

import { SECTIONS } from "./sections";
import { useCurrentSection } from "./useCurrentSection";

/**
 * The scroll-tracking index, parked in the left gutter on wide screens (it is
 * display:none below 1440px, where there is no gutter to put it in — the
 * masthead's running head carries the same information there instead).
 *
 * Every entry is a real anchor and every entry is legible at rest; the current
 * one just gains ink weight and a violet rule.
 */
export function SideIndex() {
  const current = useCurrentSection();

  return (
    <nav className="sidex" aria-label="Contents">
      <ol>
        {SECTIONS.map((s) => (
          <li key={s.id}>
            <a href={`#${s.id}`} data-on={s.id === current ? "1" : "0"}>
              <span className="sx-num">{s.num}</span>
              <span className="sx-lab">{s.label}</span>
            </a>
          </li>
        ))}
      </ol>
    </nav>
  );
}

"use client";

import { useState } from "react";

/**
 * PLATE 01 — the portal artwork tipped in at full measure, with a numbered
 * FIGURE KEY beneath it, the way a printed plate is annotated.
 *
 * The interaction is the editorial one, not a flashy one: each key entry shows
 * its number and title at rest and expands to its sentence when you open it
 * (hover on a pointer, tap/click or keyboard anywhere), and whichever entry is
 * open or hovered lights its marker on the plate. The captions live BELOW the
 * image rather than floating over it, so nothing overflows the plate edge and
 * nothing is unreadable on a phone.
 *
 * One entry is open on first paint, so the section says something at rest.
 */
export type PlateMark = {
  /** 1-based figure number. */
  n: number;
  /** Marker position over the plate, in per-cent of its box. */
  x: number;
  y: number;
  title: string;
  body: string;
};

export function PortalPlate({
  src,
  width,
  height,
  alt,
  marks,
}: {
  src: string;
  width: number;
  height: number;
  alt: string;
  marks: PlateMark[];
}) {
  const [open, setOpen] = useState<number>(marks[0]?.n ?? 1);
  const [hot, setHot] = useState<number | null>(null);
  const lit = hot ?? open;

  return (
    <div>
      <div className="plate-stage">
        <img src={src} alt={alt} width={width} height={height} />
        {marks.map((m) => (
          <button
            key={m.n}
            type="button"
            className="fig-mark"
            style={{ left: `${m.x}%`, top: `${m.y}%` }}
            data-on={lit === m.n ? "1" : "0"}
            aria-label={`Figure ${m.n}: ${m.title}`}
            onMouseEnter={() => setHot(m.n)}
            onMouseLeave={() => setHot(null)}
            onFocus={() => setHot(m.n)}
            onBlur={() => setHot(null)}
            onClick={() => setOpen(m.n)}
          >
            {m.n}
          </button>
        ))}
      </div>

      <div className="fig-key">
        {marks.map((m) => (
          <div key={m.n} data-open={open === m.n ? "1" : "0"}>
            <button
              type="button"
              aria-expanded={open === m.n}
              onMouseEnter={() => setHot(m.n)}
              onMouseLeave={() => setHot(null)}
              onFocus={() => setHot(m.n)}
              onBlur={() => setHot(null)}
              onClick={() => setOpen(m.n)}
            >
              <span className="fk-n">{`0${m.n}`.slice(-2)}</span>
              <span className="fk-t">{m.title}</span>
            </button>
            <div className="fk-more">Read</div>
            <div className="fk-body">
              <div>
                <p>{m.body}</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import Link from "next/link";

/**
 * I — THE CATALOGUE. A picture index: the whole live game catalogue as a set
 * typographic index, A to Z, with a sticky plate on the left that shows the
 * key art of whichever line you are pointing at.
 *
 * Alphabetical ON PURPOSE. There is no honest popularity signal in the schema
 * (lib/games.ts says as much: `featured` marks a tier INSIDE a family, not a
 * favoured game), so the page refuses to imply a ranking and prints an index
 * instead — which is also the more editorial object.
 *
 * Plate loading: posters are fetched on demand and then kept mounted, so the
 * first row's art is on the page at rest and every later hover cross-fades from
 * cache rather than re-requesting. Eagerly mounting all 40-odd posters would be
 * several megabytes for artwork the reader may never point at.
 */
export type CatRow = {
  family: string;
  name: string;
  /** Pre-joined genre string, e.g. "Survival · RPG". Empty when untagged. */
  genres: string;
  /** Poster slug under /games/art — null when that family has no cover art. */
  poster: string | null;
  href: string;
  priceFrom: string;
  ramTo: string;
  slotsTo: string;
};

export function Catalogue({ rows }: { rows: CatRow[] }) {
  const [at, setAt] = useState(0);
  const [seen, setSeen] = useState<number[]>([0]);

  const point = (i: number) => {
    setAt(i);
    setSeen((prev) => (prev.includes(i) ? prev : [...prev, i]));
  };

  const cur = rows[at] ?? rows[0];

  return (
    <div className="cat">
      <div className="cat-plate-col" aria-hidden="true">
        <div className="cat-plate">
          {seen.map((i) => {
            const r = rows[i];
            if (!r?.poster) return null;
            return (
              <img
                key={r.family}
                src={`/games/art/${r.poster}_poster.jpg`}
                alt=""
                data-on={i === at ? "1" : "0"}
                decoding="async"
              />
            );
          })}
        </div>
        <div className="cat-plate-cap">
          <div className="cpc-name">{cur?.name}</div>
          <div className="cap">
            <b>{`Fig. ${String(at + 1).padStart(2, "0")}`}</b>
            {cur?.genres ? ` · ${cur.genres}` : ""} · key art
          </div>
        </div>
      </div>

      <div>
        <div className="cat-index">
          <div className="cat-cols" aria-hidden="true">
            <span className="lab">Nº</span>
            <span className="lab">Title</span>
            <span className="lab">Genre</span>
            <span className="lab" style={{ textAlign: "right" }}>
              RAM to
            </span>
            <span className="lab" style={{ textAlign: "right" }}>
              Slots
            </span>
            <span className="lab" style={{ textAlign: "right" }}>
              From / mo
            </span>
          </div>

          <ol>
            {rows.map((r, i) => (
              <li className="cat-row" key={r.family}>
                <Link
                  href={r.href}
                  onMouseEnter={() => point(i)}
                  onFocus={() => point(i)}
                >
                  {r.poster ? (
                    <img
                      className="cat-thumb"
                      src={`/games/art/${r.poster}_poster.jpg`}
                      alt=""
                      loading="lazy"
                      decoding="async"
                    />
                  ) : (
                    <span className="cat-thumb" />
                  )}
                  <span className="cat-num">{String(i + 1).padStart(2, "0")}</span>
                  <span className="cat-cell-stack">
                    <span className="cat-name">{r.name}</span>
                    <span className="cat-gen-inline">
                      {r.genres}
                      {r.genres ? " · " : ""}
                      from {r.priceFrom}
                    </span>
                  </span>
                  <span className="cat-gen">{r.genres}</span>
                  <span className="cat-num-cell">{r.ramTo}</span>
                  <span className="cat-num-cell">{r.slotsTo}</span>
                  <span className="cat-price">{r.priceFrom}</span>
                </Link>
              </li>
            ))}
          </ol>
        </div>

        <div className="cat-foot">
          <span className="cap">
            Every family with a live plan, {rows.length} in all. Prices are the monthly
            renewal rate; first terms are lower.
          </span>
          <Link href="/game-servers" className="cap">
            <b>All game servers →</b>
          </Link>
        </div>
      </div>
    </div>
  );
}

