1	/* ===========================================================================
2	   Nxeon v6 — "Editorial". The bake-off's only LIGHT concept.
3	
4	   Every rule is scoped under `.v6`. The root layout's globals.css is a
5	   dark-first system: `body` carries a hardcoded #060a14 ground with two fixed
6	   radial washes and a light text colour, and ~4,700 Tailwind colour utilities
7	   sitewide resolve against a dark palette. So this file:
8	
9	     - paints its OWN ground and ink on `.v6` (never inherits a token), and
10	       pins a fixed paper layer behind the page so an overscroll bounce or a
11	       short viewport can't reveal the dark body underneath;
12	     - uses NO Tailwind utilities at all in the markup. That is partly taste
13	       (a print page wants named editorial classes, not utility soup) and
14	       partly defence: a scoped rule like `.v6 .plate { position: relative }`
15	       has specificity 0,2,0 and silently beats Tailwind's `lg:absolute`
16	       (0,1,0). With no utilities in play there is nothing to lose that fight.
17	
18	   PALETTE — a cool paper, explicitly NOT the warm-cream / terracotta /
19	   broadsheet-hairline look, which is the single most recognisable
20	   AI-generated-design cliché. The ground is a blue-biased off-white, the ink
21	   is a deep blue-black, and the accent is a printerly violet-blue drawn from
22	   the brand's own blue -> violet gradient. Saturated colour is left to the
23	   photographic plates: on paper the dark neon artwork does all the shouting,
24	   which is exactly how a monograph works.
25	   =========================================================================== */
26	
27	.v6 {
28	  /* ---- ground ---------------------------------------------------------- */
29	  --paper: #eff1f6; /* cool blue-grey paper — the page */
30	  --plate: #fafbfd; /* brighter stock — plates, tables, raised sheets */
31	  --press: #e3e7ef; /* pressed band — sunken sections */
32	  --press-deep: #d9dee8; /* pressed band, second step */
33	
34	  /* ---- ink ------------------------------------------------------------- */
35	  --ink: #11151e; /* deep blue-black, never pure black */
36	  --ink-soft: #454f61; /* body copy */
37	  --ink-mute: #78829a; /* captions, labels, folios */
38	  --ink-faint: #a3abbd;
39	
40	  /* ---- rules ----------------------------------------------------------- */
41	  --rule: #c4cbd9; /* visible division */
42	  --hair: #dbe0ea; /* hairline between index rows */
43	
44	  /* ---- accent: ink and highlighter, not a brand wash ------------------- */
45	  --violet: #4a1fcc; /* printerly violet ink — rules, markers, one solid CTA */
46	  --electric: #1a52d6; /* brand blue, for links */
47	  --wash: #d6e1ff; /* highlighter block behind hovered words */
48	
49	  --edge: clamp(18px, 4.6vw, 68px);
50	  --measure: 1280px;
51	
52	  position: relative;
53	  isolation: isolate;
54	  min-height: 100vh;
55	  background: var(--paper);
56	  color: var(--ink);
57	  font-family: var(--font-v6-text), "Helvetica Neue", Helvetica, Arial, sans-serif;
58	  font-size: 16px;
59	  line-height: 1.6;
60	  font-synthesis-weight: none;
61	  -webkit-font-smoothing: antialiased;
62	  -moz-osx-font-smoothing: grayscale;
63	  text-rendering: optimizeLegibility;
64	}
65	
66	/* The fixed paper backdrop. `body` keeps its dark gradient (not ours to
67	   change), so this covers the viewport regardless of scroll position. */
68	.v6::before {
69	  content: "";
70	  position: fixed;
71	  inset: -20vh 0;
72	  z-index: -1;
73	  background: var(--paper);
74	  pointer-events: none;
75	}
76	
77	.v6 *,
78	.v6 *::before,
79	.v6 *::after {
80	  box-sizing: border-box;
81	}
82	
83	.v6 a {
84	  color: inherit;
85	  text-decoration: none;
86	}
87	
88	.v6 ::selection {
89	  background: var(--wash);
90	  color: var(--ink);
91	}
92	
93	.v6 :focus-visible {
94	  outline: 2px solid var(--violet);
95	  outline-offset: 3px;
96	}
97	
98	.v6 img {
99	  display: block;
100	  max-width: 100%;
101	}
102	
103	.v6 p,
104	.v6 h1,
105	.v6 h2,
106	.v6 h3,
107	.v6 figure,
108	.v6 ol,
109	.v6 ul,
110	.v6 table {
111	  margin: 0;
112	  padding: 0;
113	}
114	
115	.v6 ol,
116	.v6 ul {
117	  list-style: none;
118	}
119	
120	/* ---------------------------------------------------------------------------
121	   MEASURE
122	   --------------------------------------------------------------------------- */
123	.v6 .sheet {
124	  width: 100%;
125	  max-width: var(--measure);
126	  margin-inline: auto;
127	  padding-inline: var(--edge);
128	}
129	
130	/* ---------------------------------------------------------------------------
131	   TYPE
132	   --------------------------------------------------------------------------- */
133	.v6 .disp {
134	  font-family: var(--font-v6-display), "Didot", "Bodoni MT", Georgia, serif;
135	  font-weight: 500;
136	  font-optical-sizing: auto;
137	  color: var(--ink);
138	  letter-spacing: -0.005em;
139	}
140	
141	.v6 .disp em,
142	.v6 .disp i {
143	  font-style: italic;
144	  font-weight: 400;
145	}
146	
147	.v6 .mono {
148	  font-family: var(--font-v6-mono), ui-monospace, "SFMono-Regular", Menlo, monospace;
149	  font-weight: 400;
150	  font-variant-numeric: tabular-nums;
151	}
152	
153	/* Tracked-out technical label. The page's third voice. */
154	.v6 .lab {
155	  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
156	  font-size: 10.5px;
157	  font-weight: 400;
158	  letter-spacing: 0.2em;
159	  text-transform: uppercase;
160	  color: var(--ink-mute);
161	  line-height: 1.5;
162	}
163	
164	.v6 .lab-ink {
165	  color: var(--ink);
166	}
167	
168	.v6 .h-xl {
169	  font-size: clamp(38px, 7.1vw, 90px);
170	  line-height: 0.97;
171	}
172	
173	.v6 .h-lg {
174	  font-size: clamp(30px, 4.4vw, 56px);
175	  line-height: 1.03;
176	}
177	
178	.v6 .h-md {
179	  font-size: clamp(22px, 2.5vw, 31px);
180	  line-height: 1.15;
181	}
182	
183	.v6 .deck {
184	  font-size: clamp(16.5px, 1.35vw, 19.5px);
185	  line-height: 1.62;
186	  color: var(--ink-soft);
187	  max-width: 63ch;
188	}
189	
190	.v6 .deck strong {
191	  font-weight: 600;
192	  color: var(--ink);
193	}
194	
195	/* A real drop cap, three lines deep, set in the display face. */
196	.v6 .drop::first-letter {
197	  font-family: var(--font-v6-display), Georgia, serif;
198	  font-weight: 500;
199	  font-size: 4.05em;
200	  line-height: 0.78;
201	  float: left;
202	  padding: 0.06em 0.09em 0 0;
203	  color: var(--ink);
204	}
205	
206	.v6 .cap {
207	  font-family: var(--font-v6-mono), ui-monospace, Menlo, monospace;
208	  font-size: 11.5px;
209	  line-height: 1.55;
210	  color: var(--ink-mute);
211	  letter-spacing: 0.01em;
212	}
213	
214	.v6 .cap b {
215	  font-weight: 500;
216	  color: var(--ink);
217	}
218	
219	/* Highlighter: a wash block that sits behind the lower two-fifths of a word,
220	   the way a marker pen does. Used for hover states on editorial links. */
221	.v6 .hl {
222	  background-image: linear-gradient(transparent 58%, var(--wash) 58%, var(--wash) 94%, transparent 94%);
223	  background-size: 0% 100%;
224	  background-repeat: no-repeat;
225	  transition: background-size 0.24s ease;
226	}
227	
228	.v6 a:hover .hl,
229	.v6 a:focus-visible .hl {
230	  background-size: 100% 100%;
231	}
232	
233	/* ---------------------------------------------------------------------------
234	   RULES — three weights, like a printed page
235	   --------------------------------------------------------------------------- */
236	.v6 .rule-ink {
237	  border-top: 1px solid var(--ink);
238	}
239	.v6 .rule {
