16	
17	/**
18	 * Nxeon v6 — "Editorial": the bake-off's light-mode concept, built as a printed
19	 * monograph about the platform rather than a landing page for it.
20	 *
21	 * EVERY NUMBER ON THIS PAGE IS READ FROM THE DATABASE AT REQUEST TIME. That is
22	 * not decoration: over the couple of hours this file was written, the live
23	 * Plan/GamePlan rows moved (the entry VPS went from $15.98 to $12.78), so any
24	 * figure typed into the markup would already be wrong. Hence `force-dynamic`
25	 * and hence `load()` below.
26	 *
27	 * What the page deliberately does NOT contain:
28	 *   - testimonials, reviews, star ratings or trust widgets (the Review and
29	 *     Testimonial tables are empty; inventing any would be a lie);
30	 *   - customer counts, server counts, data-centre counts or continent counts;
31	 *   - partner or customer logos of any kind;
32	 *   - any region beyond the two that actually have enabled nodes.
33	 *
34	 * The only two claims not derived from a row are the two that are pre-approved:
35	 * the `99.99% network` figure, and the `online in 47 seconds` brand tagline.
36	 */
37	
38	/* ── formatting ───────────────────────────────────────────────────────────── */
39	
40	const money = (cents: number) =>
41	  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
42	
43	const num = (n: number) => n.toLocaleString("en-US");
44	
45	const gb = (mb: number) => `${Math.round(mb / 1024)} GB`;
46	
47	/** Rounded to whole degrees on purpose: a region, not a street address. */
48	const approxCoord = (lat: number, lon: number) =>
49	  `${Math.abs(Math.round(lat))}° ${lat >= 0 ? "N" : "S"} · ${Math.abs(Math.round(lon))}° ${lon >= 0 ? "E" : "W"}`;
50	
51	/**
52	 * Game landing pages that genuinely exist as routes under app/(marketing).
53	 * Checked against the directory listing rather than assumed from the slug map —
54	 * a family whose page has not been written yet links to the index instead of a
55	 * 404. (`stationeers` is the one active family with no landing page today.)
56	 */
57	const LIVE_GAME_LANDINGS = new Set([
58	  "7-days-to-die", "abiotic-factor", "ark", "ark-survival-ascended", "barotrauma",
59	  "conan-exiles", "core-keeper", "cs2", "dont-starve-together", "dragonwilds", "eco",
60	  "empyrion", "enshrouded", "factorio", "garrys-mod", "icarus", "insurgency-sandstorm",
61	  "killing-floor-2", "left-4-dead-2", "minecraft", "minecraft-bedrock", "mordhau",
62	  "necesse", "nightingale", "palworld", "project-zomboid", "rust", "satisfactory",
63	  "sons-of-the-forest", "soulmask", "space-engineers", "squad", "sunkenland",
64	  "terraria", "tf2", "the-forest", "the-isle", "unturned", "v-rising", "valheim",
