/* Renders a STATIC approximation of app/newwebsitev6 to an HTML file so the
   design can be screenshotted without running a Next build in the live tree.
   Markup mirrors page.tsx / Catalogue.tsx / PortalPlate.tsx by hand. */
import fs from "node:fs";
import { db } from "/opt/nxeon/lib/db";
import { regionsFrom } from "/opt/nxeon/lib/nx/catalog";
import { CUSTOMER_REGION_LABELS } from "/opt/nxeon/lib/node-regions";
import { planIntroMonthlyCents } from "/opt/nxeon/lib/intro-pricing";
import { GAME_ART_SLUG, GAME_DISPLAY, GAME_GENRES, type GameFamily } from "/opt/nxeon/lib/games";

const money = (c: number) =>
  "$" + (c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const num = (n: number) => n.toLocaleString("en-US");
const gb = (mb: number) => `${Math.round(mb / 1024)} GB`;
const approx = (lat: number, lon: number) =>
  `${Math.abs(Math.round(lat))}° ${lat >= 0 ? "N" : "S"} · ${Math.abs(Math.round(lon))}° ${lon >= 0 ? "E" : "W"}`;

const MARKS = [
  { n: 1, x: 37.5, y: 15, title: "The log", body: "Every deploy, sign-in, payment and domain change lands in one timestamped feed, so the question &ldquo;what changed on Tuesday?&rdquo; has an answer you can read yourself." },
  { n: 2, x: 24, y: 30, title: "Your machines", body: "A server you actually hold the keys to: root, a console in the browser, SFTP, and backups you can put on a schedule." },
  { n: 3, x: 88, y: 24, title: "Game worlds", body: "Game servers sit in the same account as the websites — one login, one wallet, one invoice at the end of the month." },
  { n: 4, x: 91, y: 76, title: "Domains", body: "Register a name and point it at the server without leaving the page, or bring one you already own and keep it where it is." },
];

const NAV: [string, string][] = [
  ["Game servers", "/game-servers"], ["Cloud VPS", "/vps"], ["Hosting", "/web-hosting"],
  ["Domains", "/domains"], ["Mods", "/mods"], ["Price list", "/pricing"],
];

const SECTIONS = [
  { id: "v6-front", num: "—", label: "Front matter" },
  { id: "v6-catalogue", num: "I", label: "The catalogue" },
  { id: "v6-rooms", num: "II", label: "Two rooms" },
  { id: "v6-spec", num: "III", label: "Specification" },
  { id: "v6-colophon", num: "IV", label: "Colophon" },
];

const FOOT = [
  { head: "Products", links: ["Cloud VPS", "Game servers", "Web hosting", "Domains", "Mods & plugins"] },
  { head: "Company", links: ["About", "Contact", "Status", "For developers", "Features"] },
  { head: "Reading", links: ["Price list", "Blog", "Help centre", "Legal", "Sign in"] },
];

async function main() {
  const [nodes, plans, gamePlans, modCount, templates] = await Promise.all([
    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
    db.gamePlan.findMany({ where: { active: true }, select: { gameFamily: true, ramMB: true, slots: true, priceCents: true }, orderBy: { priceCents: "asc" } }),
    db.gameMod.count({ where: { active: true, upstreamOk: true } }),
    db.osTemplate.findMany({ where: { active: true }, select: { name: true, category: true, licenseRequired: true }, orderBy: { name: "asc" } }),
  ]);

  const regions = regionsFrom(nodes).slice().sort((a, b) => a.lon - b.lon).map((r) => ({
    key: r.key, label: CUSTOMER_REGION_LABELS[r.key] ?? r.name, area: r.area,
    iso: r.flag.toUpperCase(), coord: approx(r.lat, r.lon),
  }));
  const regionNames = regions.map((r) => r.label).join(" · ");

  const byFamily = new Map<string, { from: number; ram: number; slots: number }>();
  for (const p of gamePlans) {
    const prev = byFamily.get(p.gameFamily);
    if (!prev) { byFamily.set(p.gameFamily, { from: p.priceCents, ram: p.ramMB, slots: p.slots ?? 0 }); continue; }
    prev.from = Math.min(prev.from, p.priceCents);
    prev.ram = Math.max(prev.ram, p.ramMB);
    prev.slots = Math.max(prev.slots, p.slots ?? 0);
  }
  const catalogue = [...byFamily.entries()].flatMap(([k, a]) => {
    if (!(k in GAME_DISPLAY)) return [];
    const f = k as GameFamily;
    return [{
      name: GAME_DISPLAY[f].name,
      genres: (GAME_GENRES[f] ?? []).join(" · "),
      poster: GAME_ART_SLUG[f].poster ?? null,
      priceFrom: money(a.from), ramTo: gb(a.ram), slotsTo: a.slots > 0 ? String(a.slots) : "—",
    }];
  }).sort((a, b) => a.name.localeCompare(b.name, "en"));

  const isGame = (n: string) => / Server$/.test(n);
  const groups = [
    { label: "Operating systems", items: templates.filter((t) => t.category === "PLAIN_OS") },
    { label: "Control panels", items: templates.filter((t) => t.category === "CONTROL_PANEL") },
    { label: "Applications", items: templates.filter((t) => t.category === "APPLICATION" && !isGame(t.name)) },
  ].filter((g) => g.items.length);
  const gameImageCount = templates.filter((t) => isGame(t.name)).length;
  const licenced = templates.filter((t) => t.licenseRequired).length;

  const entry = plans[0];
  const entryIntro = entry ? planIntroMonthlyCents(entry) : null;
  const cheapestGame = gamePlans[0];
  const cheapestGameName = cheapestGame && cheapestGame.gameFamily in GAME_DISPLAY
    ? GAME_DISPLAY[cheapestGame.gameFamily as GameFamily].name : null;
  const gameFrom = cheapestGame ? money(cheapestGame.priceCents) : null;

  const css = fs.readFileSync("/opt/nxeon/app/newwebsitev6/v6.css", "utf8");

  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,opsz,wght@0,6..96,400..700;1,6..96,400..700&family=Libre+Franklin:ital,wght@0,300..700;1,400&family=DM+Mono:wght@300;400;500&display=swap" rel="stylesheet">
<style>
:root{--font-v6-display:'Bodoni Moda';--font-v6-text:'Libre Franklin';--font-v6-mono:'DM Mono'}
*{margin:0;padding:0;box-sizing:border-box}
html,body{background:#060a14;color:#eaf2ff}
img{display:block;max-width:100%}
ol,ul{list-style:none}
button{font:inherit}
table{border-collapse:collapse}
${css}
</style></head><body><div class="v6">

<header class="mast"><div class="sheet mast-in">
  <a class="brand" href="#"><img src="/nx-mark.png" alt="" width="61" height="30"><span class="wordmark">Nxeon</span></a>
  <nav class="mast-nav">${NAV.map(([l]) => `<a href="#">${l}</a>`).join("")}</nav>
  <div class="runhead"><span class="rh-num disp">I</span><span class="lab">The catalogue</span></div>
  <span class="mast-sign lab">The catalogue</span>
  <button class="contents-btn">Contents</button>
</div></header>

<nav class="sidex"><ol>${SECTIONS.map((s, i) => `<li><a href="#${s.id}" data-on="${i === 1 ? 1 : 0}"><span class="sx-num">${s.num}</span><span class="sx-lab">${s.label}</span></a></li>`).join("")}</ol></nav>

<section id="v6-front">
 <div class="sheet hero">
  <div>
   <div class="hero-kicker"><span class="lab lab-ink">Nxeon · a working catalogue</span><span class="kick-rule"></span><span class="lab">Nº 01</span></div>
   <h1 class="disp h-xl">Everything your company runs on, <em>online in 47&nbsp;seconds.</em></h1>
   <p class="deck">Websites, stores, the quiet machines nobody ever sees — and the game world your team disappears into on Fridays. Two regions, NVMe throughout, and a panel nobody has to explain to you.</p>
   <div class="btn-row">
    <a class="btn-ink" href="#">Deploy a server ${arrow()}</a>
    <a class="btn-text" href="#">Read the price list ${arrow()}</a>
   </div>
  </div>
  <aside class="colophon">
   ${entry ? `<div class="cph-row"><span class="lab">Entry VPS</span><span class="cph-val">${money(entry.priceCents)}<small>/mo</small></span><span class="cph-sub">${entryIntro ? `first term ${money(entryIntro)} · ` : ""}${entry.cpuCores} vCPU · ${gb(entry.ramMB)} · ${entry.diskGB} GB NVMe</span></div>` : ""}
   <div class="cph-row"><span class="lab">Game worlds</span><span class="cph-val">${catalogue.length}</span><span class="cph-sub">families with live plans${gameFrom ? ` · from ${gameFrom}/mo` : ""}</span></div>
   <div class="cph-row"><span class="lab">Mod catalogue</span><span class="cph-val">${num(modCount)}</span><span class="cph-sub">active entries, upstream verified</span></div>
   <div class="cph-row"><span class="lab">One-click images</span><span class="cph-val">${templates.length}</span><span class="cph-sub">systems, panels, apps &amp; game servers</span></div>
   <div class="cph-row"><span class="lab">Regions</span><span class="cph-val">${regions.length === 2 ? "Two" : regions.length}</span><span class="cph-sub">${regionNames}</span></div>
  </aside>
 </div>

 <div class="plate-band"><div class="sheet plate-wrap">
  <div class="plate-head"><span class="lab lab-ink">Plate 01 · the panel</span><span class="cap">Point at a number to read its note. Everything below is one account.</span></div>
  <div>
   <div class="plate-stage">
    <img src="/nx/art/activity-hero.webp" alt="" width="1400" height="471">
    ${MARKS.map((m) => `<button class="fig-mark" style="left:${m.x}%;top:${m.y}%" data-on="${m.n === 1 ? 1 : 0}">${m.n}</button>`).join("")}
   </div>
   <div class="fig-key">${MARKS.map((m) => `<div data-open="${m.n === 1 ? 1 : 0}"><button><span class="fk-n">0${m.n}</span><span class="fk-t">${m.title}</span></button><div class="fk-more">Read</div><div class="fk-body"><div><p>${m.body}</p></div></div></div>`).join("")}</div>
  </div>
 </div></div>
</section>

<section id="v6-catalogue">
 <figure class="bleed-plate">
  <img class="bp-img" src="/games/art/vrising_hero.jpg" alt="" width="2560" height="1392">
  <div class="sheet"><figcaption><span class="cap"><b>Plate 02</b> · V Rising — publisher key art</span><span class="cap">One of ${catalogue.length} worlds in the index below</span></figcaption></div>
 </figure>
 <div class="sheet sec">
  <div class="opener"><div class="op-num disp">I</div><div>
   <div class="op-lab lab">The catalogue</div>
   <div class="op-body">
    <h2 class="disp h-lg">Every world we run, <em>set in alphabetical order.</em></h2>
    <p class="deck drop">There are ${catalogue.length} game families with live plans right now, and no honest way to rank them — a &ldquo;most popular&rdquo; badge would be a decoration, not a measurement. So this is an index rather than a chart: A to Z, with the cheapest live tier, the memory ceiling and the slot ceiling for each. Point at a line to see its key art.</p>
   </div></div></div>

  <div class="cat">
   <div class="cat-plate-col">
    <div class="cat-plate"><img src="/games/art/${catalogue[0].poster}_poster.jpg" alt="" data-on="1"></div>
    <div class="cat-plate-cap"><div class="cpc-name">${catalogue[0].name}</div><div class="cap"><b>Fig. 01</b> · ${catalogue[0].genres} · key art</div></div>
   </div>
   <div>
    <div class="cat-index">
     <div class="cat-cols"><span class="lab">Nº</span><span class="lab">Title</span><span class="lab">Genre</span><span class="lab" style="text-align:right">RAM to</span><span class="lab" style="text-align:right">Slots</span><span class="lab" style="text-align:right">From / mo</span></div>
     <ol>${catalogue.map((r, i) => `<li class="cat-row"><a href="#">${r.poster ? `<img class="cat-thumb" src="/games/art/${r.poster}_poster.jpg" alt="" loading="lazy">` : `<span class="cat-thumb"></span>`}<span class="cat-num">${String(i + 1).padStart(2, "0")}</span><span class="cat-cell-stack"><span class="cat-name">${r.name}</span><span class="cat-gen-inline">${r.genres} · from ${r.priceFrom}</span></span><span class="cat-gen">${r.genres}</span><span class="cat-num-cell">${r.ramTo}</span><span class="cat-num-cell">${r.slotsTo}</span><span class="cat-price">${r.priceFrom}</span></a></li>`).join("")}</ol>
    </div>
    <div class="cat-foot"><span class="cap">Every family with a live plan, ${catalogue.length} in all. Prices are the monthly renewal rate; first terms are lower.</span><a href="#" class="cap cap-link"><b>All game servers →</b></a></div>
   </div>
  </div>
 </div>
</section>

<section id="v6-rooms"><div class="sheet sec">
 <div class="opener"><div class="op-num disp">II</div><div>
  <div class="op-lab lab">Two rooms</div>
  <div class="op-body">
   <h2 class="disp h-lg">Two rooms. <em>Choose the nearer one.</em></h2>
   <p class="deck">Nxeon runs in exactly two places, and the page is not going to pretend otherwise with a map full of dots. ${regionNames} — on a <strong>99.99% network</strong>, which is the only availability figure we will put in print.</p>
  </div></div></div>
 <div class="rooms-lead">
  <blockquote class="pull">A shorter route is the only performance claim that survives contact with reality.</blockquote>
  <figure class="rooms-art"><img src="/nx/art/server-stack.webp" alt="" width="900" height="977"><figcaption class="cap"><b>Plate 03</b> · the stack</figcaption></figure>
 </div>
 <div class="rooms">${regions.map((r, i) => `<article class="room"><div class="room-ord">${String(i + 1).padStart(2, "0")}</div><h3>${r.label}</h3><dl><div class="room-line"><dt>Continent</dt><dd>${r.area}</dd></div><div class="room-line"><dt>Approx.</dt><dd>${r.coord}</dd></div><div class="room-line"><dt>Country</dt><dd>${r.iso}</dd></div><div class="room-line"><dt>Runs</dt><dd>VPS · game servers · hosting</dd></div></dl></article>`).join("")}</div>
 <div class="rooms-note"><span class="cap">Read from the live node table at page load — a region appears here only once something can actually be deployed into it.</span><a href="#" class="cap cap-link"><b>Network status →</b></a></div>
</div></section>

<section id="v6-spec" class="spec-band"><div class="sheet sec">
 <div class="opener"><div class="op-num disp">III</div><div>
  <div class="op-lab lab">Specification</div>
  <div class="op-body">
   <h2 class="disp h-lg">The price list, <em>as printed.</em></h2>
   <p class="deck">The whole VPS range, straight from the catalogue. The right-hand column is the renewal rate — the number to plan around. The left-hand one is the first term, which is lower.</p>
  </div></div></div>
 <div class="spec-scroll"><table class="spec">
  <thead><tr><th>Plan</th><th>vCPU</th><th>Memory</th><th>NVMe</th><th>Transfer</th><th>First term</th><th>Renews at</th></tr></thead>
  <tbody>${plans.map((p) => { const i2 = planIntroMonthlyCents(p); return `<tr><td><span class="sp-name">${p.name}</span></td><td><span class="sp-fig">${p.cpuCores}</span></td><td><span class="sp-fig">${gb(p.ramMB)}</span></td><td><span class="sp-fig">${p.diskGB} GB</span></td><td><span class="sp-fig">${p.bandwidthTB} TB</span></td><td><span class="sp-price">${i2 ? money(i2) : "—"}</span></td><td><span class="sp-renew">${money(p.priceCents)} / mo</span></td></tr>`; }).join("")}</tbody>
 </table></div>
 <div class="spec-note">
  <p>First-term rates apply to your first billing term and then renew at the rate in the right-hand column. Longer terms carry their own discount, shown before you pay. Every tier is NVMe throughout, with root access and a console in the browser.</p>
  ${cheapestGame && cheapestGameName ? `<p>Game worlds are priced separately and start at <strong>${gameFrom}/mo</strong> — ${gb(cheapestGame.ramMB)}${cheapestGame.slots ? ` and ${cheapestGame.slots} slots` : ""} on the entry tier for ${cheapestGameName}.</p>` : ""}
 </div>
 <div class="imgs">
  <div class="plate-head"><span class="lab lab-ink">One-click images</span><span class="cap">${templates.length} in the catalogue today, ${gameImageCount} of them game servers (indexed in section I)</span></div>
  <div class="imgs-list">${groups.map((g) => `<div class="imgs-group"><div class="lab">${g.label}</div><ul>${g.items.map((t) => `<li>${t.name}${t.licenseRequired ? `<span class="v6-dagger">†</span>` : ""}</li>`).join("")}</ul></div>`).join("")}</div>
  ${licenced ? `<p class="cap" style="padding-top:14px">† Licence bought separately from its vendor. Nxeon deploys the image; it does not resell the licence.</p>` : ""}
 </div>
</div></section>

<section id="v6-colophon"><div class="sheet sec-tight">
 <div class="close">
  <div>
   <div class="op-lab lab">IV · Colophon</div>
   <h2 class="disp h-xl">Put something of your own <em>online.</em></h2>
   <div class="btn-row"><a class="btn-ink" href="#">Deploy a server ${arrow()}</a><a class="btn-text" href="#">Start a game world ${arrow()}</a></div>
  </div>
  <div class="close-side">
   <p class="cap">A card, a region, a name — nothing else. ${regionNames}, whichever is closer to the people who will use it.</p>
   ${entry ? `<p class="cap" style="padding-top:10px">Entry tier ${money(entry.priceCents)}/mo${entryIntro ? `, first term ${money(entryIntro)}` : ""}.</p>` : ""}
  </div>
 </div>
 <footer class="foot">
  <div class="foot-cols">
   <div class="foot-brand"><img src="/nx-mark.png" alt="Nxeon" width="61" height="30"><p>Servers, sites and game worlds in ${regionNames}. Deployed from one account, billed from one wallet.</p></div>
   ${FOOT.map((c) => `<div><div class="lab lab-ink">${c.head}</div><ul>${c.links.map((l) => `<li><a href="#"><span class="hl">${l}</span></a></li>`).join("")}</ul></div>`).join("")}
  </div>
  <div class="foot-fine"><span class="cap">Nxeon · ${regionNames} · concept sheet v6, not indexed</span><span class="cap">Every figure on this sheet read live from the catalogue at page load</span></div>
 </footer>
</div></section>

</div></body></html>`;

  fs.writeFileSync("/tmp/claude-0/-root/ec6fa978-d80b-4147-9982-eea470598e2c/scratchpad/v6-preview.html", html);
  console.log("written", html.length, "bytes · families", catalogue.length, "· templates", templates.length);
}

function arrow() {
  return `<svg class="v6-arrow" width="13" height="13" viewBox="0 0 16 16" fill="none"><path d="M1.5 8h12" stroke="currentColor" stroke-width="1.1"/><path d="M9 3.5 13.5 8 9 12.5" stroke="currentColor" stroke-width="1.1" fill="none"/></svg>`;
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });

