1	/* Renders a STATIC approximation of app/newwebsitev6 to an HTML file so the
2	   design can be screenshotted without running a Next build in the live tree.
3	   Markup mirrors page.tsx / Catalogue.tsx / PortalPlate.tsx by hand. */
4	import fs from "node:fs";
5	import { db } from "/opt/nxeon/lib/db";
6	import { regionsFrom } from "/opt/nxeon/lib/nx/catalog";
7	import { CUSTOMER_REGION_LABELS } from "/opt/nxeon/lib/node-regions";
8	import { planIntroMonthlyCents } from "/opt/nxeon/lib/intro-pricing";
9	import { GAME_ART_SLUG, GAME_DISPLAY, GAME_GENRES, type GameFamily } from "/opt/nxeon/lib/games";
10	
11	const money = (c: number) =>
