13	const num = (n: number) => n.toLocaleString("en-US");
14	const gb = (mb: number) => `${Math.round(mb / 1024)} GB`;
15	const approx = (lat: number, lon: number) =>
16	  `${Math.abs(Math.round(lat))}° ${lat >= 0 ? "N" : "S"} · ${Math.abs(Math.round(lon))}° ${lon >= 0 ? "E" : "W"}`;
17	
18	const MARKS = [
19	  { n: 1, x: 58, y: 26, title: "The log", body: "Every deploy, sign-in, payment and domain change lands in one timestamped feed, so the question &ldquo;what changed on Tuesday?&rdquo; has an answer you can read yourself." },
20	  { n: 2, x: 24, y: 30, title: "Your machines", body: "A server you actually hold the keys to: root, a console in the browser, SFTP, and backups you can put on a schedule." },
21	  { n: 3, x: 88, y: 24, title: "Game worlds", body: "Game servers sit in the same account as the websites — one login, one wallet, one invoice at the end of the month." },
22	  { n: 4, x: 91, y: 76, title: "Domains", body: "Register a name and point it at the server without leaving the page, or bring one you already own and keep it where it is." },
23	];
24	
25	const NAV: [string, string][] = [
26	  ["Game servers", "/game-servers"], ["Cloud VPS", "/vps"], ["Hosting", "/web-hosting"],
27	  ["Domains", "/domains"], ["Mods", "/mods"], ["Price list", "/pricing"],
28	];
29	
30	const SECTIONS = [
31	  { id: "v6-front", num: "—", label: "Front matter" },
32	  { id: "v6-catalogue", num: "I", label: "The catalogue" },
33	  { id: "v6-rooms", num: "II", label: "Two rooms" },
34	  { id: "v6-spec", num: "III", label: "Specification" },
35	  { id: "v6-colophon", num: "IV", label: "Colophon" },
36	];
37	
38	const FOOT = [
39	  { head: "Products", links: ["Cloud VPS", "Game servers", "Web hosting", "Domains", "Mods & plugins"] },
40	  { head: "Company", links: ["About", "Contact", "Status", "For developers", "Features"] },
41	  { head: "Reading", links: ["Price list", "Blog", "Help centre", "Legal", "Sign in"] },
42	];
43	
44	async function main() {
45	  const [nodes, plans, gamePlans, modCount, templates] = await Promise.all([
46	    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
47	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
48	    db.gamePlan.findMany({ where: { active: true }, select: { gameFamily: true, ramMB: true, slots: true, priceCents: true }, orderBy: { priceCents: "asc" } }),
49	    db.gameMod.count({ where: { active: true, upstreamOk: true } }),
50	    db.osTemplate.findMany({ where: { active: true }, select: { name: true, category: true, licenseRequired: true }, orderBy: { name: "asc" } }),
51	  ]);
52	
53	  const regions = regionsFrom(nodes).slice().sort((a, b) => a.lon - b.lon).map((r) => ({
54	    key: r.key, label: CUSTOMER_REGION_LABELS[r.key] ?? r.name, area: r.area,
55	    iso: r.flag.toUpperCase(), coord: approx(r.lat, r.lon),
56	  }));
57	  const regionNames = regions.map((r) => r.label).join(" · ");
58	
59	  const byFamily = new Map<string, { from: number; ram: number; slots: number }>();
60	  for (const p of gamePlans) {
61	    const prev = byFamily.get(p.gameFamily);
62	    if (!prev) { byFamily.set(p.gameFamily, { from: p.priceCents, ram: p.ramMB, slots: p.slots ?? 0 }); continue; }
63	    prev.from = Math.min(prev.from, p.priceCents);
64	    prev.ram = Math.max(prev.ram, p.ramMB);
65	    prev.slots = Math.max(prev.slots, p.slots ?? 0);
66	  }
67	  const catalogue = [...byFamily.entries()].flatMap(([k, a]) => {
68	    if (!(k in GAME_DISPLAY)) return [];
69	    const f = k as GameFamily;
70	    return [{
71	      name: GAME_DISPLAY[f].name,
72	      genres: (GAME_GENRES[f] ?? []).join(" · "),
73	      poster: GAME_ART_SLUG[f].poster ?? null,
74	      priceFrom: money(a.from), ramTo: gb(a.ram), slotsTo: a.slots > 0 ? String(a.slots) : "—",
75	    }];
76	  }).sort((a, b) => a.name.localeCompare(b.name, "en"));
77	
78	  const isGame = (n: string) => / Server$/.test(n);
79	  const groups = [
80	    { label: "Operating systems", items: templates.filter((t) => t.category === "PLAIN_OS") },
81	    { label: "Control panels", items: templates.filter((t) => t.category === "CONTROL_PANEL") },
82	    { label: "Applications", items: templates.filter((t) => t.category === "APPLICATION" && !isGame(t.name)) },
83	  ].filter((g) => g.items.length);
84	  const gameImageCount = templates.filter((t) => isGame(t.name)).length;
85	  const licenced = templates.filter((t) => t.licenseRequired).length;
86	
87	  const entry = plans[0];
88	  const entryIntro = entry ? planIntroMonthlyCents(entry) : null;
89	  const cheapestGame = gamePlans[0];
90	  const cheapestGameName = cheapestGame && cheapestGame.gameFamily in GAME_DISPLAY
91	    ? GAME_DISPLAY[cheapestGame.gameFamily as GameFamily].name : null;
92	  const gameFrom = cheapestGame ? money(cheapestGame.priceCents) : null;
93	
94	  const css = fs.readFileSync("/opt/nxeon/app/newwebsitev6/v6.css", "utf8");
95	
96	  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
97	<meta name="viewport" content="width=device-width,initial-scale=1">
98	<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
99	<link href="https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,opsz,wght@0,6..96,400..700;1,6..96,400..700&family=Libre+Franklin:ital,wght@0,300..700;1,400&family=DM+Mono:wght@300;400;500&display=swap" rel="stylesheet">
100	<style>
101	:root{--font-v6-display:'Bodoni Moda';--font-v6-text:'Libre Franklin';--font-v6-mono:'DM Mono'}
102	*{margin:0;padding:0;box-sizing:border-box}
103	html,body{background:#060a14;color:#eaf2ff}
104	img{display:block;max-width:100%}
105	ol,ul{list-style:none}
106	button{font:inherit}
107	table{border-collapse:collapse}
108	${css}
109	</style></head><body><div class="v6">
110	
111	<header class="mast"><div class="sheet mast-in">
112	  <a class="brand" href="#"><img src="/nx-mark.png" alt="" width="61" height="30"><span class="wordmark">Nxeon</span></a>
113	  <nav class="mast-nav">${NAV.map(([l]) => `<a href="#">${l}</a>`).join("")}</nav>
114	  <div class="runhead"><span class="rh-num disp">I</span><span class="lab">The catalogue</span></div>
115	  <span class="mast-sign lab">The catalogue</span>
116	  <button class="contents-btn">Contents</button>
117	</div></header>
118	
119	<nav class="sidex"><ol>${SECTIONS.map((s, i) => `<li><a href="#${s.id}" data-on="${i === 1 ? 1 : 0}"><span class="sx-num">${s.num}</span><span class="sx-lab">${s.label}</span></a></li>`).join("")}</ol></nav>
